cd /echo && cat > zz_repro_test.go <<'EOF'
package echo

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestZZGroupRepro(t *testing.T) {
	e := New()
	h := func(c Context) error { return c.String(http.StatusOK, "h") }
	m1 := func(next HandlerFunc) HandlerFunc {
		return func(c Context) error { fmt.Println("m1"); return next(c) }
	}
	m2 := func(next HandlerFunc) HandlerFunc {
		return func(c Context) error { fmt.Println("m2"); return next(c) }
	}
	g1 := e.Group("/group", m1)
	g1.GET("", h)
	g2 := e.Group("/group", m2)
	g2.GET("/other", h)

	for _, p := range []string{"/group", "/group/other"} {
		req := httptest.NewRequest(http.MethodGet, p, nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		fmt.Printf("%s -> %d %q\n", p, rec.Code, rec.Body.String())
	}
}

func TestZZMapBindRepro(t *testing.T) {
	e := New()
	req := httptest.NewRequest(http.MethodGet, "/?tag=a&tag=b", nil)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)
	defer func() {
		if r := recover(); r != nil {
			fmt.Println("PANIC:", r)
		}
	}()
	m := map[string][]string{}
	err := c.Bind(&m)
	fmt.Println("map[string][]string err:", err, "val:", m)

	m2 := map[string]interface{}{}
	err = c.Bind(&m2)
	fmt.Println("map[string]interface{} err:", err, "val:", m2)
}
EOF
go test -run 'TestZZGroupRepro|TestZZMapBindRepro' -v . 2>&1 | head -40
